require_once MODX_CORE_PATH . 'components/andromedda/andromedda.class.php';

$limit = (int)($scriptProperties['limit'] ?? 4);
$data = Andromedda::loadCatalog();
$products = array_values(array_filter($data['products'] ?? [], static fn($p) => !empty($p['isPopular'])));
if (count($products) < $limit) {
    $products = array_slice($data['products'] ?? [], 0, $limit);
} else {
    $products = array_slice($products, 0, $limit);
}

$html = '';
foreach ($products as $i => $product) {
    $html .= '<div class="min-w-0">' . Andromedda::productCardHtml($modx, $product, $i < 2) . '</div>';
}

return $html;
